              },
              "spatial_setup": {
                "type": "string",
                "description": "本镜背景区域的固定空间关系。"
              }
            },
            "required": [
              "scene_id",
              "state",
              "spatial_setup"
            ],
            "additionalProperties": false
          },
          "characters": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "character_id": {
                  "type": "string",
                  "description": "关联人物ID；无资产时为空。"
                },
                "costume_id": {
                  "type": "string",
                  "description": "选定服装ID；无服装目录时为空。"
                },
                "name": {
                  "type": "string",
                  "description": "对象名称。",
                  "minLength": 1
                },
                "presence": {
                  "type": "string",
                  "description": "开场在场与入画状态。"
                },
                "position": {
                  "type": "string",
                  "description": "开场空间位置。"
                },
                "facing": {
                  "type": "string",
                  "description": "开场身体朝向。"
                },
                "gaze_target": {
                  "type": "string",
                  "description": "开场目光对象。"
                }
              },
              "required": [
